def prepare_geometries(module_name="tools.glm_perf.reconstruction_native"):
    import importlib

    native = importlib.import_module(module_name)
    DECODE_ROWS, GLM_GEOMETRIES, ProjectionGeometry = (
        native.DECODE_ROWS,
        native.GLM_GEOMETRIES,
        native.ProjectionGeometry,
    )

    shapes = ((128, 256), (256, 512), *GLM_GEOMETRIES)
    return tuple(
        ProjectionGeometry(rows, experts, n, k) for experts in (3, 72) for n, k in shapes for rows in DECODE_ROWS
    )

def prepare():
    import importlib, hashlib, sys
    from pathlib import Path
    import importlib.util
    package = 'glm_reconstruction_v2_helpers'
    package_root = Path('/home/matteius/experiments/glm-reconstruction-20261006/build-native-n64-v2/glm_reconstruction_v2_helpers')
    if package not in sys.modules:
        spec = importlib.util.spec_from_file_location(package, package_root/'__init__.py', submodule_search_locations=[str(package_root)])
        module = importlib.util.module_from_spec(spec)
        sys.modules[package] = module
        spec.loader.exec_module(module)
    if Path(sys.modules[package].__file__).resolve() != (package_root/'__init__.py').resolve():
        raise ValueError('native helper package already belongs to another build')
    helpers = {'glm_reconstruction_v2_helpers.glm_int4': '973cc57ac55319ecb21bca6ef9186efd1bf60a38ffc4595d2143a5eeef566b11', 'glm_reconstruction_v2_helpers.reconstruction_native': '9bf814f721c063009c3e211841a55f7940c849c99d018d0822227f1cc3f5752c', 'glm_reconstruction_v2_helpers.reconstruction_probe': '28bed5d13f232d03d7783ee2d2d3d68ccba7db608ba78804b35a9bfeb7cdf50a', 'glm_reconstruction_v2_helpers.expert_reconstruction': 'da4a2a03a57fbf79972609c4d703910bfe5932a2847af5ddf7c626e0aa2c358c'}
    for name, expected in helpers.items():
        module = importlib.import_module(name)
        if hashlib.sha256(Path(module.__file__).read_bytes()).hexdigest() != expected:
            raise ValueError('worker helper differs from manifest: ' + name)
    from glm_reconstruction_v2_helpers.glm_int4 import NativeW4Projection
    root = Path('/home/matteius/experiments/glm-reconstruction-20261006/build-native-n64-v2')
    geometries = prepare_geometries('glm_reconstruction_v2_helpers.reconstruction_native')
    resources = {'w4a8': NativeW4Projection(root/'glm_w4a8_pack.bin', root/'glm_w4a8_matmul.bin', geometries, namespace='glm_reconstruction_v2')}
    return resources

def validate(resources):
    from glm_reconstruction_v2_helpers.reconstruction_probe import component_cases, gate_case, graph_gate
    records = [gate_case(resources['w4a8'], geometry, repeats=2) for geometry in component_cases()]
    graph_gate(resources['w4a8'], component_cases()[2])
    return {'passed': True, 'cases': len(records), 'weight_format': 'unchanged_signed_block32', 'activation_format': 'new_group32_int8', 'model_quality': 'not_evaluated'}
